<script>
    import { onMount } from 'svelte';
    import '@xterm/xterm/css/xterm.css';

    let termContainer;
    let socket;
    let term;

    // THE FIX: Safely exported getLogs function so the UI doesn't crash
    export function getLogs() {
        try {
            if (!term || !term.buffer) return "";
            const lines = term.buffer.active.length;
            let logs = "";
            for (let i = Math.max(0, lines - 30); i < lines; i++) {
                const line = term.buffer.active.getLine(i);
                if (line) logs += line.translateToString() + "\n";
            }
            return logs;
        } catch (e) {
            return "";
        }
    }

    export function triggerCommand(cmd) {
        if (socket && socket.readyState === WebSocket.OPEN) {
            socket.send(cmd + "\r");
        }
    }

    onMount(async () => {
        const { Terminal } = await import('@xterm/xterm');
        const { FitAddon } = await import('@xterm/addon-fit');

        term = new Terminal({
            cursorBlink: true,
            fontSize: 12,
            fontFamily: '"JetBrains Mono", monospace',
            theme: { background: '#000000', foreground: '#00ff00', cursor: '#00ff00' }
        });

        const fitAddon = new FitAddon();
        term.loadAddon(fitAddon);
        term.open(termContainer);
        fitAddon.fit();

        const proto = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
        socket = new WebSocket(`${proto}//${window.location.host}/ws`);

        socket.onmessage = (event) => { term.write(event.data); };

        term.onData((data) => {
            if (socket.readyState === WebSocket.OPEN) socket.send(data);
        });

        window.addEventListener('resize', () => fitAddon.fit());
    });
</script>

<div class="h-full w-full bg-black p-2 overflow-hidden" bind:this={termContainer}></div>
```

The `Terminal.svelte` component provides an interactive terminal interface within the UI. It utilizes the `@xterm/xterm` library to render a fully functional terminal emulator. The component establishes a WebSocket connection to a backend server (determined by the current protocol - HTTP or HTTPS) to facilitate communication. It allows sending commands to the server via the `triggerCommand` function and displays the server's responses within the terminal. The `getLogs` function allows retrieval of the last 30 lines of terminal output. The terminal automatically resizes to fit its container using the `FitAddon`. Essentially, it's a remote shell interface embedded in the web application.

