<script>
    import { onMount } from 'svelte';

    let isConnected = false;
    let lastPing = null;

    onMount(() => {
        const ws = new WebSocket(window.location.protocol === 'https:' ? 'wss://' : 'ws://') + window.location.host + '/heartbeat';

        ws.onopen = () => {
            isConnected = true;
            lastPing = Date.now();
            console.log('Heartbeat connected');
        };

        ws.onmessage = () => {
            lastPing = Date.now();
        };

        ws.onclose = () => {
            isConnected = false;
            console.log('Heartbeat disconnected');
        };

        ws.onerror = (error) => {
            console.error('Heartbeat error:', error);
        };

        return () => {
            ws.close();
        };
    });
</script>

